from pathlib import Path
import json, html, re
from urllib.parse import quote
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'content/portfolio.json').read_text())
esc=html.escape
IG='https://www.instagram.com/a1maquetas/'
ABC='https://www.abc.com.py/edicion-impresa/suplementos/empresas-y-negocios/maquetas-1424849.html'
ABC2='https://www.abc.com.py/edicion-impresa/notas/maqueta-del-santuario-para-el-santo-padre-1386430.html'
def icon(kind='arrow'):
 p={'arrow':'<path d="M4 12h15M13 5l7 7-7 7"/>','external':'<path d="M5 19 19 5M5 5h14v14"/>','left':'<path d="m14 5-7 7 7 7"/>','right':'<path d="m9 5 7 7-7 7"/>','close':'<path d="m6 6 12 12M6 18 18 6"/>','plus':'<path d="M12 4v16M4 12h16"/>','expand':'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5"/>'}[kind]
 return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">{p}</svg>'
def logo():return '<span class="logo-symbol">A1<span class="logo-dot"></span></span><span class="logo-word">MAQUETAS<span>ARQUITECTÓNICAS</span></span>'
def header(active):
 links=[('index.html','Inicio'),('proyectos.html','Portafolio'),('nosotros.html','Nosotros')]
 return f'''<a class="skip" href="#contenido">Saltar al contenido</a><header class="header"><div class="shell header-inner"><a class="logo" href="index.html" aria-label="A1 Maquetas, inicio">{logo()}</a><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false"><span>Menú</span><span class="menu-lines" aria-hidden="true"></span></button><nav class="main-nav" id="main-nav" aria-label="Navegación principal">{''.join(f'<a href="{url}" '+('aria-current="page"' if active==label else '')+f'>{label}</a>' for url,label in links)}<a class="nav-quote" href="cotizacion.html" {'aria-current="page"' if active=='Cotización' else ''}>Cotizar un proyecto {icon('external')}</a><a class="nav-instagram" href="{IG}" target="_blank" rel="noopener noreferrer" aria-label="A1 Maquetas en Instagram, abre una pestaña nueva">Instagram {icon('external')}</a></nav></div></header>'''
def footer():return f'''<footer class="footer"><div class="shell"><div class="footer-top"><a class="logo" href="index.html" aria-label="A1 Maquetas, inicio">{logo()}</a><p>Arquitectura que se puede<br>mirar, recorrer y tocar.</p><a class="footer-social" href="{IG}" target="_blank" rel="noopener noreferrer">Encontranos en Instagram {icon('external')}</a></div><div class="footer-links"><div><span>Explorar</span><a href="proyectos.html">Portafolio</a><a href="nosotros.html">Nosotros</a><a href="cotizacion.html">Cotización</a></div><div><span>Portafolio</span>{''.join(f'<a href="{c["id"]}.html">{c["name"]}</a>' for c in data)}</div><div class="footer-place"><span>Desde Asunción, Paraguay.</span><p>Más de 20 años haciendo maquetas.<br>Trabajos nacionales e internacionales.</p></div></div><div class="footer-bottom"><span>© 2026 A1 Maquetas</span><span>Diseño y desarrollo por NovaTec Engineering</span><a href="#top">Volver al inicio {icon('external')}</a></div></div></footer>'''
def cta():return f'''<section class="cta"><div class="shell cta-inner"><div><span class="eyebrow">Tu próximo proyecto</span><h2>Hagamos tangible<br>tu idea.</h2></div><div><p>Conocé qué necesitamos para preparar<br>una cotización y empezar a conversar.</p><a class="button button-light" href="cotizacion.html">Preparar una cotización {icon('arrow')}</a></div></div></section>'''
def bread(label,parent=None):return f'<nav class="breadcrumb shell" aria-label="Ruta de navegación"><a href="index.html">Inicio</a><span>/</span>'+('<a href="proyectos.html">Portafolio</a><span>/</span>' if parent else '')+f'<span aria-current="page">{label}</span></nav>'
def page(name,title,desc,body,active='Portafolio'):
 content=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0C3B45"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{esc(desc)}"><meta property="og:title" content="{esc(title)} | A1 Maquetas"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:locale" content="es_PY"><meta property="og:image" content="https://thiago15da.github.io/dental/assets/photos/a1-residencial.jpg"><meta property="og:image:alt" content="Maqueta residencial de A1, fotografía de archivo"><meta name="twitter:card" content="summary_large_image"><title>{esc(title)} | A1 Maquetas</title><link rel="icon" href="favicon.svg"><link rel="preload" href="assets/fonts/manrope-regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="a1.css?v=20261028"><script defer src="a1.js?v=20261028"></script></head><body id="top">{header(active)}<main id="contenido">{body}</main>{footer()}<dialog class="lightbox" id="lightbox" aria-label="Fotografía ampliada"><button class="lightbox-close" aria-label="Cerrar fotografía">{icon('close')}</button><img src="assets/photos/a1-residencial.jpg" alt=""><p></p></dialog></body></html>'''
 (ROOT/name).write_text(content)
def categories():
 return ''.join(f'<a class="category-tile" href="{c["id"]}.html"><div class="tile-top"><span>0{i+1}</span>{icon("external")}</div><div class="category-symbol symbol-{c["id"]}" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="tile-bottom"><h3>{c["name"]}</h3><span>{len(c["projects"]):02d} proyectos</span></div></a>' for i,c in enumerate(data))
def requirements():return f'''<div class="requirements"><article><span class="require-number">01</span><h3>Legajo de obra</h3><p>La documentación del proyecto para entender su forma y sus dimensiones.</p><span class="require-tag">La base del proyecto</span></article><article><span class="require-number">02</span><h3>Perspectivas</h3><p>Las vistas que ayudan a interpretar la propuesta y sus detalles.</p><span class="require-tag">La intención visual</span></article><article><span class="require-number">03</span><h3>Modelo 3D</h3><p>El modelo digital para conocer los volúmenes y las relaciones espaciales.</p><span class="require-tag">La información en volumen</span></article></div>'''
def gallery():return f'''<section class="gallery shell" aria-label="Fotografías del trabajo de A1" aria-roledescription="carrusel" tabindex="0"><div class="gallery-stage"><figure class="gallery-slide is-active" data-slide="0" role="group" aria-roledescription="diapositiva" aria-label="1 de 2"><img src="assets/photos/a1-residencial.jpg" width="1920" height="1503" fetchpriority="high" alt="Maqueta de edificio residencial de A1, con balcones, árboles y figuras a escala. Archivo ABC Color, 2015."><figcaption><span>01 / Arquitectura a escala</span><strong>La diferencia está<br>en cada detalle.</strong></figcaption></figure><figure class="gallery-slide" data-slide="1" role="group" aria-roledescription="diapositiva" aria-label="2 de 2" hidden><img src="assets/photos/a1-caacupe.jpg" width="770" height="499" alt="Maqueta del santuario de Caacupé realizada por Hernán Kiss. Archivo ABC Color, 2015."><figcaption><span>02 / Archivo del taller</span><strong>Una historia<br>que toma forma.</strong></figcaption></figure><button class="gallery-expand" aria-label="Ampliar fotografía actual">{icon('expand')}<span>Ampliar</span></button><span class="gallery-side-label" aria-hidden="true">DESLIZÁ / DESCUBRÍ EL DETALLE</span></div><div class="gallery-toolbar"><div class="gallery-index"><span id="slideNumber">01</span><span class="gallery-track"><i></i></span><span>02</span></div><p class="gallery-hint">Deslizá para descubrir</p><div class="gallery-controls"><button data-gallery-prev aria-label="Fotografía anterior">{icon('left')}</button><button data-gallery-next aria-label="Fotografía siguiente">{icon('right')}</button></div></div><div class="gallery-source"><span id="slideCaption" aria-live="polite">Maqueta residencial · Fotografía de archivo</span><a id="slideSource" href="{ABC}" target="_blank" rel="noopener noreferrer">Archivo A1 / ABC Color, 2015 {icon('external')}</a></div></section>'''
home=f'''<section class="home-intro shell"><div><span class="eyebrow"><i></i>Maquetas arquitectónicas</span><h1>Ideas que se<br>pueden <em>tocar.</em></h1></div><div class="intro-aside"><span class="small-caps">Asunción, Paraguay / Desde el detalle</span><p>Más de 20 años convirtiendo<br>proyectos en experiencias tangibles.</p><a class="text-link" href="proyectos.html">Ver proyectos {icon('arrow')}</a></div></section>{gallery()}<section class="portfolio-section shell"><div class="section-heading"><div><span class="eyebrow">01 / Portafolio</span><h2>Una escala para<br>cada idea.</h2></div><p>Edificios, territorios, espacios y piezas singulares.<br>Cinco maneras de acercarnos a la arquitectura.</p></div><div class="category-grid">{categories()}</div></section><section class="about-band"><div class="shell about-grid"><div class="experience-number"><span>+20</span><p>Años de experiencia<br>haciendo maquetas.</p></div><div><span class="eyebrow">02 / Nosotros</span><h2>Hecho en Asunción.<br>Con una mirada<br><em>sin fronteras.</em></h2><p>Somos A1 Maquetas. Desde Asunción, trabajamos en proyectos nacionales e internacionales, llevando cada idea al terreno de lo tangible.</p><a class="text-link" href="nosotros.html">Conocé A1 {icon('arrow')}</a></div></div></section><section class="quote-preview shell"><div class="section-heading"><div><span class="eyebrow">03 / Empecemos un proyecto</span><h2>Una buena maqueta<br>empieza con información.</h2></div><a class="text-link" href="cotizacion.html">Qué necesitamos para cotizar {icon('arrow')}</a></div>{requirements()}</section>{cta()}'''
page('index.html','Maquetas arquitectónicas en Asunción','A1 Maquetas. Más de 20 años haciendo maquetas en Asunción, con trabajos nacionales e internacionales. Explorá nuestro portafolio.',home,'Inicio')
# Full portfolio: a quiet editorial directory with filters, all names supplied by A1.
rows=[]
for c in data:
 for j,name in enumerate(c['projects']):
  n=len(rows)+1
  rows.append(f'<article class="project-row" data-category="{c["id"]}" data-project-name="{esc(name)}"><span class="project-number">{n:02d}</span><h3><a href="{c["id"]}.html#proyecto-{j+1}">{name}</a></h3><a class="project-category" href="{c["id"]}.html">{c["name"]}</a><a class="project-open" href="{c["id"]}.html#proyecto-{j+1}" aria-label="Ver {esc(name)} en {c["name"]}">{icon("external")}</a></article>')
portfolio=f'''{bread('Portafolio')}<section class="page-intro shell"><span class="eyebrow">Portafolio / A1 Maquetas</span><h1>Proyectos con<br><em>otra perspectiva.</em></h1><div class="page-lead"><p>Una selección del trabajo de A1, organizada por la forma en que cada proyecto se lleva a escala.</p><span class="catalog-count">17 proyectos / 05 categorías</span></div></section><section class="catalog shell" aria-label="Catálogo de proyectos"><div class="catalog-tools"><div class="filters" role="group" aria-label="Filtrar proyectos"><button data-filter="todos" aria-pressed="true">Todos <span>17</span></button>{''.join(f'<button data-filter="{c["id"]}" aria-pressed="false">{c["name"]} <span>{len(c["projects"])}</span></button>' for c in data)}</div><label class="search"><span>Buscar proyecto</span><input id="projectSearch" type="search" placeholder="Nombre del proyecto" autocomplete="off"></label></div><div class="catalog-meta"><span>Nombre del proyecto</span><span id="resultCount" role="status">17 proyectos</span></div><div class="project-list">{''.join(rows)}</div><div class="empty-state" hidden><h2>No encontramos ese proyecto.</h2><p>Probá con otro nombre o explorá todas las categorías.</p><button class="button" id="resetFilters">Ver todos los proyectos {icon('arrow')}</button></div></section><section class="archive-banner shell"><div><span class="eyebrow">El trabajo, de cerca</span><h2>Seguí el día a día<br>del taller.</h2><p>Más fotografías y novedades de A1 en Instagram.</p><a class="text-link" href="{IG}" target="_blank" rel="noopener noreferrer">@a1maquetas {icon('external')}</a></div><figure><button class="image-open" data-lightbox="assets/photos/a1-residencial.jpg" data-caption="Maqueta residencial de A1 · Archivo ABC Color, 2015" aria-label="Ampliar fotografía de archivo de A1"><img src="assets/photos/a1-residencial.jpg" width="1920" height="1503" loading="lazy" alt="Detalle de una maqueta residencial de A1, fotografía de archivo.">{icon('expand')}</button><figcaption>Fotografía de archivo · ABC Color, 2015. No corresponde a una ficha del listado.</figcaption></figure></section>{cta()}'''
page('proyectos.html','Portafolio','Edificios, loteamientos, viviendas, especiales y maquetas hápticas. Explorá los proyectos de A1 Maquetas.',portfolio)
for i,c in enumerate(data):
 names=''.join(f'<article class="category-project" id="proyecto-{j+1}"><span>{j+1:02d}</span><div><h2>{esc(n)}</h2><p>{c["name"]} / A1 Maquetas</p></div><a class="text-link" href="cotizacion.html?referencia={quote(n)}">Consultar {icon("arrow")}</a></article>' for j,n in enumerate(c['projects']))
 nxt=data[(i+1)%len(data)]
 body=f'''{bread(c['name'],True)}<section class="category-intro shell"><div><span class="eyebrow">Portafolio / 0{i+1}</span><h1>{c['name']}<span class="title-count">{len(c['projects']):02d}</span></h1><h2>{c['title']}</h2><p>{c['description']}</p></div><div class="category-graphic" aria-hidden="true"><div class="category-symbol symbol-{c['id']}"><i></i><i></i><i></i><i></i></div><span>A1 / {c['name'].upper()}</span></div></section><section class="shell category-selection"><div class="catalog-meta"><span>Selección de proyectos</span><span>{len(c['projects']):02d} trabajos</span></div>{names}<p class="collection-note">Las fotografías de esta selección se incorporarán a la galería. Mientras tanto, podés conocer más del taller en <a href="{IG}" target="_blank" rel="noopener noreferrer">Instagram</a>.</p></section><section class="next-category shell"><span class="eyebrow">Seguí explorando</span><a href="{nxt['id']}.html"><span>{nxt['name']}</span>{icon('arrow')}</a></section>{cta()}'''
 page(c['id']+'.html',c['name'],c['description'],body)
about=f'''{bread('Nosotros')}<section class="page-intro shell"><span class="eyebrow">Nosotros / A1 Maquetas</span><h1>Un oficio.<br><em>Muchas perspectivas.</em></h1><div class="page-lead"><p>Somos de Asunción y hemos realizado trabajos internacionales. Hace más de 20 años hacemos maquetas: ideas que se convierten en piezas para mirar de cerca.</p></div></section><section class="about-story shell"><div class="about-story-photo"><img src="assets/photos/a1-residencial.jpg" width="1920" height="1503" alt="Fachada y detalles de una maqueta residencial A1, archivo de 2015."><a class="photo-credit" href="{ABC}" target="_blank" rel="noopener noreferrer">Archivo A1 / ABC Color, 2015 {icon('external')}</a></div><div class="about-story-copy"><span class="eyebrow">Nuestra forma de mirar</span><h2>La arquitectura<br>se entiende mejor<br>cuando toma forma.</h2><p>Un plano propone. Una maqueta acerca. Permite observar un proyecto desde otra perspectiva y reconocer la relación entre el conjunto y sus detalles.</p><p>En A1, el trabajo de Hernán Kiss y el taller se expresa en edificios, loteamientos, viviendas, piezas especiales y maquetas hápticas.</p><div class="signature">Hernán Kiss<span>A1 Maquetas / Asunción, Paraguay</span></div></div></section><section class="about-band"><div class="shell about-grid"><div class="experience-number"><span>+20</span><p>Años de experiencia<br>haciendo maquetas.</p></div><div><span class="eyebrow">Origen y trayectoria</span><h2>Desde Paraguay.<br>Para proyectos<br><em>sin fronteras.</em></h2><p>Nuestro punto de partida es Asunción. Nuestra experiencia incluye trabajos nacionales e internacionales, con una misma atención puesta en cada maqueta.</p></div></div></section><section class="shell principles"><span class="eyebrow">Tres formas de acercarnos a una idea</span><div class="principle-grid"><article><span>01</span><h2>Escala.</h2><p>Encontrar la relación que permite comprender el proyecto.</p></article><article><span>02</span><h2>Materia.</h2><p>Dar una presencia tangible a la propuesta arquitectónica.</p></article><article><span>03</span><h2>Detalle.</h2><p>Hacer que cada parte dialogue con el conjunto.</p></article></div></section>{cta()}'''
page('nosotros.html','Nosotros','A1 Maquetas, Asunción. Más de 20 años de experiencia haciendo maquetas y trabajos nacionales e internacionales.',about,'Nosotros')
quote_body=f'''{bread('Cotización')}<section class="page-intro shell"><span class="eyebrow">Cotización / Empecemos por tu idea</span><h1>El primer paso<br>es <em>conocer tu proyecto.</em></h1><div class="page-lead"><p>Para cotizar una maqueta necesitamos el legajo de obra, las perspectivas y el modelo 3D. Reuní esa información y conversemos sobre lo que querés representar.</p></div></section><section class="shell quote-requirements" aria-label="Qué necesitamos para cotizar">{requirements()}</section><section class="brief-section shell"><div class="brief-intro"><span class="eyebrow">Prepará tu consulta</span><h2>De la idea<br>a la conversación.</h2><p>Organizá los datos de tu proyecto. Al terminar, podés copiar tu consulta y enviárnosla por Instagram.</p><p class="brief-help">Los archivos se comparten al coordinar con el taller. Si todavía te falta algún material, podés indicarlo en tu consulta.</p><a class="text-link" href="{IG}" target="_blank" rel="noopener noreferrer">Ir a @a1maquetas {icon('external')}</a></div><form id="briefForm" class="brief-form"><div class="field-grid"><label>Tu nombre<input name="nombre" required maxlength="100" autocomplete="name" placeholder="¿Cómo te llamás?"></label><label>Tipo de proyecto<select name="categoria" required><option value="">Elegí una categoría</option>{''.join(f'<option>{c["name"]}</option>' for c in data)}</select></label></div><label>Nombre o referencia del proyecto<input name="referencia" id="briefReference" maxlength="120" placeholder="Nombre del proyecto (opcional)"></label><fieldset><legend>¿Qué documentación tenés disponible?</legend><p>Marcá los materiales que ya tenés.</p><div class="document-checks"><label><input type="checkbox" name="documentos" value="Legajo de obra"><span>Legajo de obra</span></label><label><input type="checkbox" name="documentos" value="Perspectivas"><span>Perspectivas</span></label><label><input type="checkbox" name="documentos" value="Modelo 3D"><span>Modelo 3D</span></label></div><span id="documentProgress" class="document-progress" role="status">0 de 3 materiales disponibles</span></fieldset><label>Contanos sobre tu idea<textarea name="detalles" rows="4" maxlength="1600" placeholder="Qué querés representar, para qué presentación o qué te gustaría conversar."></textarea></label><button class="button" type="submit">Preparar consulta {icon('arrow')}</button><p class="form-note">Podés revisar el texto antes de copiarlo. Nada se envía automáticamente.</p></form></section><section class="brief-result shell" id="briefResult" hidden aria-labelledby="briefResultTitle"><div><span class="eyebrow">Tu consulta está lista</span><h2 id="briefResultTitle" tabindex="-1">Revisá. Copiá.<br>Conversemos.</h2><p>Copiá el texto y pegalo en un mensaje a @a1maquetas.</p></div><div><label for="briefText">Texto de tu consulta</label><textarea id="briefText" rows="10"></textarea><div class="brief-actions"><button class="button" id="copyBrief">Copiar consulta {icon('arrow')}</button><a class="button button-outline" href="{IG}" target="_blank" rel="noopener noreferrer">Abrir Instagram {icon('external')}</a></div><p id="copyStatus" role="status"></p></div></section>'''
page('cotizacion.html','Cotizá tu maqueta','Qué necesitamos para cotizar: legajo de obra, perspectivas y modelo 3D. Prepará tu consulta para A1 Maquetas.',quote_body,'Cotización')
