for old,target in {'contacto.html':'cotizacion.html','taller.html':'nosotros.html','explorador.html':'proyectos.html','mundo.html':'proyectos.html','wtc-asuncion.html':'edificios.html','basilica-caacupe.html':'especiales.html'}.items():
 (ROOT/old).write_text(f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url={target}"><title>A1 Maquetas</title><link rel="stylesheet" href="a1.css?v=20261028"></head><body><main class="shell page-intro"><h1>A1 Maquetas</h1><p>Continuá explorando nuestro trabajo.</p><a class="button" href="{target}">Ir al portafolio</a></main></body></html>')
